K(y,A,B)[x:=N]=
\begin{cases}
K(y,A[x:=N],B),&y=x,\\
K(y,A[x:=N],B[x:=N]),&y\ne x,\ y\notin\operatorname{FV}_{imp}(N),\\
K(y',A[x:=N],(B[y:=\operatorname{var}(y')])[x:=N]),&\text{其它情形},
\end{cases}

\begin{aligned}
\mathsf{RawRule}_{imp,\mathsf{Conv}}
={}&
\{((\Gamma\vdash M:A,\Gamma\vdash A\equiv B:K),\Gamma\vdash M:B)\}\\
&\cup
\{((\Gamma\vdash M\equiv N:A,\Gamma\vdash A\equiv B:K),
\Gamma\vdash M\equiv N:B)\}.
\end{aligned}
